import{_ as t,a as o,o as d,a6 as a}from"./chunks/framework.CJDy2q7X.js";const g=JSON.parse('{"title":"Catalog Categories — Tree (Nested) (GraphQL)","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-catalog-categories-tree","title":"Category Tree (Nested)","description":"Cursor-paginated GraphQL query that returns root category nodes, each carrying its full nested subtree under `children`. Supports locale, status, and rootId filters.","query":"query AdminCatalogCategoryTrees(\\n  $first: Int\\n  $after: String\\n  $locale: String\\n  $status: Int\\n  $rootId: Int\\n) {\\n  adminCategoryTrees(\\n    first: $first\\n    after: $after\\n    locale: $locale\\n    status: $status\\n    rootId: $rootId\\n  ) {\\n    edges {\\n      cursor\\n      node {\\n        id\\n        _id\\n        name\\n        slug\\n        status\\n        position\\n        parentId\\n        displayMode\\n        children\\n      }\\n    }\\n    pageInfo {\\n      hasNextPage\\n      hasPreviousPage\\n      endCursor\\n      startCursor\\n    }\\n    totalCount\\n  }\\n}\\n","variables":"{\\n  \\"first\\": 10,\\n  \\"locale\\": \\"en\\",\\n  \\"status\\": 1\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"adminCategoryTrees\\": {\\n      \\"edges\\": [\\n        {\\n          \\"cursor\\": \\"MA==\\",\\n          \\"node\\": {\\n            \\"id\\": \\"/api/admin/admin_category_trees/1\\",\\n            \\"_id\\": 1,\\n            \\"name\\": \\"Root Category\\",\\n            \\"slug\\": \\"root\\",\\n            \\"status\\": 1,\\n            \\"position\\": 0,\\n            \\"parentId\\": null,\\n            \\"displayMode\\": null,\\n            \\"children\\": [\\n              {\\n                \\"id\\": 2,\\n                \\"name\\": \\"Apparel\\",\\n                \\"slug\\": \\"apparel\\",\\n                \\"status\\": 1,\\n                \\"position\\": 1,\\n                \\"parentId\\": 1,\\n                \\"displayMode\\": null,\\n                \\"children\\": []\\n              },\\n              {\\n                \\"id\\": 5,\\n                \\"name\\": \\"Electronics\\",\\n                \\"slug\\": \\"electronics\\",\\n                \\"status\\": 1,\\n                \\"position\\": 2,\\n                \\"parentId\\": 1,\\n                \\"displayMode\\": null,\\n                \\"children\\": []\\n              }\\n            ]\\n          }\\n        }\\n      ],\\n      \\"pageInfo\\": {\\n        \\"hasNextPage\\": false,\\n        \\"hasPreviousPage\\": false,\\n        \\"endCursor\\": \\"MA==\\",\\n        \\"startCursor\\": \\"MA==\\"\\n      },\\n      \\"totalCount\\": 1\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/catalog/categories/categories-tree.md","filePath":"api/graphql-api/admin/catalog/categories/categories-tree.md","lastUpdated":1787725411000}'),n={name:"api/graphql-api/admin/catalog/categories/categories-tree.md"};function r(s,e,i,c,l,h){return d(),o("div",null,e[0]||(e[0]=[a(`<h1 id="catalog-categories-—-tree-nested-graphql" tabindex="-1">Catalog Categories — Tree (Nested) (GraphQL) <a class="header-anchor" href="#catalog-categories-—-tree-nested-graphql" aria-label="Permalink to &quot;Catalog Categories — Tree (Nested) (GraphQL)&quot;">​</a></h1><p>Cursor-paginated GraphQL query that returns the full nested category hierarchy. Each edge node represents a root-level category and carries its complete subtree under <code>children</code>. Leaf nodes have <code>children: []</code>.</p><p>This query returns the <strong>nested hierarchy</strong>, which is what a tree picker or navigation menu needs. For a flat, filterable, sortable list use <a href="/api/graphql-api/admin/catalog/categories/categories-listing.html"><code>adminCategories</code></a> instead.</p><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th><th>Pagination</th></tr></thead><tbody><tr><td><code>adminCategoryTrees</code></td><td>Query</td><td>Cursor (<code>first</code> / <code>after</code>)</td></tr></tbody></table><h2 id="arguments" tabindex="-1">Arguments <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;Arguments&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Argument</th><th>Type</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><code>first</code></td><td><code>Int</code></td><td>Number of root nodes per page (default <code>10</code>, max <code>50</code>)</td><td><code>10</code></td></tr><tr><td><code>after</code></td><td><code>String</code></td><td>Cursor from a previous <code>pageInfo.endCursor</code> for keyset pagination</td><td><code>&quot;MA==&quot;</code></td></tr><tr><td><code>locale</code></td><td><code>String</code></td><td>Locale code for name/slug resolution (default: app locale)</td><td><code>&quot;en&quot;</code></td></tr><tr><td><code>status</code></td><td><code>Int</code></td><td>Filter by status: <code>0</code> = disabled, <code>1</code> = enabled. Ancestor nodes are preserved when they have qualifying descendants.</td><td><code>1</code></td></tr><tr><td><code>rootId</code></td><td><code>Int</code></td><td>Limit the tree to descendants of this category ID (inclusive). Returns empty if the ID is unknown.</td><td><code>1</code></td></tr></tbody></table><p>Every filter is a first-class GraphQL argument — pass <code>locale</code>, <code>status</code>, and <code>rootId</code> alongside <code>first</code> and <code>after</code>, not inside a nested filter object.</p><h2 id="node-fields" tabindex="-1">Node Fields <a class="header-anchor" href="#node-fields" aria-label="Permalink to &quot;Node Fields&quot;">​</a></h2><p>Each <code>edges[].node</code> object represents a root-level category and contains:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>ID</code></td><td>API Platform IRI (e.g. <code>/api/admin/admin_category_trees/1</code>)</td></tr><tr><td><code>_id</code></td><td><code>Int</code></td><td>Raw category ID</td></tr><tr><td><code>name</code></td><td><code>String</code></td><td>Category name resolved via <code>locale</code></td></tr><tr><td><code>slug</code></td><td><code>String</code></td><td>URL slug</td></tr><tr><td><code>status</code></td><td><code>Int</code></td><td><code>1</code> = enabled, <code>0</code> = disabled</td></tr><tr><td><code>position</code></td><td><code>Int</code></td><td>Display order position</td></tr><tr><td><code>parentId</code></td><td><code>Int</code></td><td>Parent category ID; <code>null</code> for root nodes</td></tr><tr><td><code>displayMode</code></td><td><code>String</code></td><td>Category display mode</td></tr><tr><td><code>children</code></td><td>scalar (JSON array)</td><td>Nested child nodes (recursive plain objects); <code>[]</code> for leaf nodes</td></tr></tbody></table><h3 id="the-children-structure" tabindex="-1">The children Structure <a class="header-anchor" href="#the-children-structure" aria-label="Permalink to &quot;The children Structure&quot;">​</a></h3><p><code>children</code> is a <strong>plain JSON scalar</strong>, not a connection — select it bare, then walk it as an ordinary nested array with no <code>edges</code>/<code>node</code> wrappers.</p><p>Each element repeats the same shape recursively — <code>id</code>, <code>name</code>, <code>slug</code>, <code>status</code>, <code>position</code>, <code>parentId</code>, <code>displayMode</code>, <code>children</code> — down to leaves, which carry <code>children: []</code>.</p><p>One difference will catch you: <strong>a nested child identifies itself with <code>id</code> holding the numeric id</strong>, while the top-level connection node uses <code>id</code> for the IRI and <code>_id</code> for the number. So <code>node.id</code> is <code>/api/admin/admin_category_trees/1</code> but <code>node.children[0].id</code> is <code>2</code>. Read <code>_id</code> at the top level and <code>id</code> inside <code>children</code>.</p><h2 id="filtering-by-root" tabindex="-1">Filtering by Root <a class="header-anchor" href="#filtering-by-root" aria-label="Permalink to &quot;Filtering by Root&quot;">​</a></h2><p>To get the subtree rooted at a specific category, pass <code>rootId</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;first&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;rootId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;locale&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;en&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>If the <code>rootId</code> does not exist in the database, <code>totalCount</code> will be <code>0</code> and <code>edges</code> will be empty.</p><h2 id="behaviour-worth-knowing" tabindex="-1">Behaviour Worth Knowing <a class="header-anchor" href="#behaviour-worth-knowing" aria-label="Permalink to &quot;Behaviour Worth Knowing&quot;">​</a></h2><ul><li><strong>Pagination counts root nodes, not categories.</strong> <code>first</code> and <code>after</code> page through top-level nodes only, and each one always arrives with its complete subtree. A store with a single root therefore reports <code>totalCount: 1</code> no matter how many categories exist beneath it — do not read it as a category count.</li><li><strong><code>status</code> filtering keeps ancestors.</strong> With <code>status: 1</code>, a disabled parent still appears when any descendant is enabled, so the branch stays reachable.</li><li><strong>The node IRI is routeless.</strong> <code>id</code> resolves to <code>/api/admin/admin_category_trees/&lt;id&gt;</code>, which is not a queryable path. Use <code>_id</code>, and fetch a category with <a href="/api/graphql-api/admin/catalog/categories/categories-detail.html"><code>adminCategory(id:)</code></a> using <code>/api/admin/catalog/categories/&lt;_id&gt;</code>.</li><li><strong>Tree nodes carry no <code>locale</code>, <code>translations</code>, or <code>filterableAttributeIds</code>.</strong> Names and slugs are already resolved for the requested locale; for per-locale metadata use the item query.</li><li><strong>REST returns the same tree</strong> through <code>GET /api/admin/catalog/categories/tree</code>, with identical filter semantics.</li></ul>`,21)]))}const u=t(n,[["render",r]]);export{g as __pageData,u as default};
